cd /workspace/project && python3 -c "
import sys; sys.path.insert(0,'/workspace/project')
import syntax
P=syntax.parse_policy
print(P('not((startswith() or contains(a,b))) drop;'))
try: P('match(A)\x0ballow;')
except syntax.PolicyError as e: print('vt rejected:', e)
try: P('match(A) allow')
except syntax.PolicyError as e: print('no semi:', e)
print(P('match(a) allow;match(a) drop;'))
try: P('(match(a)) allow;')
except syntax.PolicyError as e: print('redundant parens:', e)
try: P('match(abcdefghijklmnopqrstuvwxy) allow;')
except syntax.PolicyError as e: print('25-char name:', e)
print(P('match(and,or,not,allow,drop) allow;'))
try: P('match(a) allow; match(b)')
except syntax.PolicyError as e: print('trailing:', e)
print(P('  \t\r\n'))
try: P('match(a) allow;;')
except syntax.PolicyError as e: print('double semi:', e)
try: P('contains(abcdefghijklmnopqrst) allow;')
except syntax.PolicyError as e: print('path>16:', e)
d='match(a)'
for i in range(15): d='not(%s)'%d
print('depth15 ok?', P(d+' allow;')[1])
d2='not(%s)'%d
try: P(d2+' allow;')
except syntax.PolicyError as e: print('depth17:', e)
"
